          "praefix": "Multae fēminae ante tabernam Albīnī ",
          "lacuna": "cōnsistunt",
          "suffix": " et ōrnāmenta eius aspiciunt.",
          "explicatio": "Verbum: cōnsistunt (gradum sistunt)."
