          "praefix": "Lydia laeta digitum suum aspicit et cum Mēdō ā tabernā ",
          "lacuna": "abit",
          "suffix": ". Lydia Mēdō viam mōnstrat.",
          "explicatio": "Verbum: abit (discēdit)."
