    "pensumC": {
      "titulus": "PĒNSVM C (Capitulum VIII)",
      "descriptio": "Interrogātiōnēs: Scrībe respōnsum Latīnē, deinde aperī exemplum!",
      "quaestiones": [
        {
          "id": "p8c_1",
          "interrogatio": "Quid Albīnus vēndit?",
          "exemplum": "Albīnus ōrnāmenta (gemmās, margarītās, ānulōs) vēndit."
        },
        {
          "id": "p8c_2",
          "interrogatio": "Ā quō Aemilia ōrnāmenta accipit?",
          "exemplum": "Aemilia ōrnāmenta ā virō suō Iūliō accipit."
        },
        {
          "id": "p8c_3",
          "interrogatio": "Ambulatne Mēdus cum dominō suō?",
          "exemplum": "Mēdus cum dominō suō nōn ambulat, sed sōlus cum Lydiā amīcā suā Rōmae ambulat."
        },
        {
          "id": "p8c_4",
          "interrogatio": "Ubi Mēdus et Lydia cōnsistunt?",
          "exemplum": "Mēdus et Lydia ante tabernam Albīnī cōnsistunt."
        },
        {
          "id": "p8c_5",
          "interrogatio": "Cūr Mēdus margarītās nōn emit?",
          "exemplum": "Mēdus margarītās nōn emit, quia Lydia iam multās margarītās habet."
        },
        {
          "id": "p8c_6",
          "interrogatio": "Cūr Lydia nūllum ānulum habet?",
          "exemplum": "Lydia nūllum ānulum habet, quia ipsa pecūniōsa nōn est, neque amīcus eius pecūniōsus est."
        },
        {
          "id": "p8c_7",
          "interrogatio": "Estne vacuus sacculus Mēdī?",
          "exemplum": "Sacculus Mēdī nōn est vacuus, sed plēnus nummōrum est (nōnāgintā sēstertiī īnsunt)."
        },
        {
          "id": "p8c_8",
          "interrogatio": "Quot sēstertiīs cōnstat ānulus gemmātus?",
          "exemplum": "Ānulus gemmātus centum (C) sēstertiīs cōnstat, sed Albīnus eum nōnāgintā (XC) sēstertiīs vēndit."
        },
        {
          "id": "p8c_9",
          "interrogatio": "Ad quem digitum ānulus convenit?",
          "exemplum": "Ānulus ad digitum quārtum convenit, nam digitus medius nimis magnus est."
        }
      ]
    }
